<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { CdcMessage, CdcMessageBox } from '../components/ui/feedback'
import { CirclePlus, Database, PlugZap, Target, Trash2 } from 'lucide-vue-next'
import { api } from '../api'
import { useAppStore } from '../stores/app'

const store=useAppStore(), route=useRoute(), dialog=ref(false), kind=ref('source'), loading=ref(false)
const sourceForm=reactive({id:null,name:'',dbType:'MYSQL',host:'127.0.0.1',port:3306,username:'root',password:'',pollIntervalMs:500,enabled:true})
const targetForm=reactive({id:null,name:'',targetType:'STARROCKS_STREAM_LOAD',host:'127.0.0.1',port:3306,endpoint:'http://127.0.0.1:18030',queryPort:19030,database:'',username:'root',password:'',bootstrapServers:'127.0.0.1:9092',enabled:true})
const title=computed(()=>`${sourceForm.id||targetForm.id?'编辑':'新增'}${kind.value==='source'?'源连接':'目标连接'}`)
const view=computed(()=>route.params.kind==='targets'?'targets':'sources')
onMounted(()=>store.loadConnections().catch(e=>CdcMessage.error(e.message)))
function add(type){kind.value=type;if(type==='source')Object.assign(sourceForm,{id:null,name:'',dbType:'MYSQL',host:'127.0.0.1',port:3306,username:'root',password:'',pollIntervalMs:500,enabled:true});else Object.assign(targetForm,{id:null,name:'',targetType:'STARROCKS_STREAM_LOAD',host:'127.0.0.1',port:3306,endpoint:'http://127.0.0.1:18030',queryPort:19030,database:'',username:'root',password:'',bootstrapServers:'127.0.0.1:9092',enabled:true});dialog.value=true}
function editSource(row){kind.value='source';Object.assign(sourceForm,row,{password:''});dialog.value=true}
function editTarget(row){kind.value='target';const c=row.config||{};Object.assign(targetForm,{id:row.id,name:row.name,targetType:row.targetType,host:c.host||'127.0.0.1',port:c.port||3306,endpoint:c.endpoint||'http://127.0.0.1:18030',queryPort:c.queryPort||19030,database:c.database||'',username:c.username||'root',password:'',bootstrapServers:c.bootstrapServers||'127.0.0.1:9092',enabled:row.enabled});dialog.value=true}
function sourceTypeChanged(){sourceForm.port=sourceForm.dbType==='SQLSERVER'?1433:sourceForm.dbType==='STARROCKS'?9030:3306}
async function save(){loading.value=true;try{let path,body,id;if(kind.value==='source'){id=sourceForm.id;path='/sources';body={...sourceForm,databaseName:''}}else{id=targetForm.id;path='/targets';const f=targetForm;let config;if(f.targetType==='KAFKA')config={bootstrapServers:f.bootstrapServers};else if(f.targetType==='STARROCKS_STREAM_LOAD')config={endpoint:f.endpoint,queryPort:f.queryPort,database:f.database,username:f.username,password:f.password};else config={host:f.host,port:f.port,database:f.database,username:f.username,password:f.password};body={id:f.id,name:f.name,targetType:f.targetType,config,enabled:f.enabled}}await api(path+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(body)});dialog.value=false;await store.loadConnections();CdcMessage.success('连接已保存')}catch(e){CdcMessage.error(e.message)}finally{loading.value=false}}
async function probe(type,row){try{const result=await api(`/${type}s/${row.id}/probe`,{method:'POST'});result.reachable?CdcMessage.success(result.detail||`连接正常${result.tables!=null?'，发现 '+result.tables+' 张表':''}`):CdcMessage.error(result.error||'连接失败')}catch(e){CdcMessage.error(e.message)}}
async function remove(type,row){try{await CdcMessageBox.confirm('删除连接前必须先移除引用它的同步任务。','确认删除',{type:'warning'});await api(`/${type}s/${row.id}`,{method:'DELETE'});await store.loadConnections();CdcMessage.success('连接已删除')}catch(e){if(e!=='cancel')CdcMessage.error(e.message)}}
</script>

<template>
  <div class="connections-layout">
    <aside class="connections-subnav" aria-label="连接类型">
      <div class="subnav-heading"><span>数据连接</span><small>资源配置</small></div>
      <nav>
        <RouterLink to="/connections/sources" :class="{active:view==='sources'}"><Database :size="17"/><span>源连接</span><b>{{ store.sources.length }}</b></RouterLink>
        <RouterLink to="/connections/targets" :class="{active:view==='targets'}"><Target :size="17"/><span>目标连接</span><b>{{ store.targets.length }}</b></RouterLink>
      </nav>
    </aside>
    <section class="connections-content">
      <header class="page-header"><div><div class="eyebrow">数据连接 / {{ view==='sources'?'源连接':'目标连接' }}</div><h1>{{ view==='sources'?'源连接':'目标连接' }}</h1><p>{{ view==='sources'?'管理 CDC 抓取来源和元数据访问。':'管理同步任务写入目标和投递配置。' }}</p></div><div class="header-actions"><cdc-button type="primary" @click="add(view==='sources'?'source':'target')"><CirclePlus :size="16"/>新增{{ view==='sources'?'源':'目标' }}连接</cdc-button></div></header>
      <section class="panel connections-panel" v-if="view==='sources'"><cdc-table :data="store.sources"><cdc-table-column prop="name" label="名称" min-width="180"/><cdc-table-column prop="dbType" label="类型" width="140"/><cdc-table-column label="地址" min-width="220"><template #default="{row}"><span class="mono">{{row.host}}:{{row.port}}</span></template></cdc-table-column><cdc-table-column prop="pollIntervalMs" label="轮询间隔" width="120"><template #default="{row}">{{row.pollIntervalMs}} ms</template></cdc-table-column><cdc-table-column label="能力" width="130"><template #default="{row}"><cdc-tag :type="row.dbType==='STARROCKS'?'warning':'success'" size="small">{{row.dbType==='STARROCKS'?'轮询模式':'严格 CDC'}}</cdc-tag></template></cdc-table-column><cdc-table-column label="状态" width="90"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></cdc-table-column><cdc-table-column label="操作" width="230"><template #default="{row}"><div class="connection-actions"><cdc-button size="small" @click="probe('source',row)"><PlugZap :size="14"/>测试</cdc-button><cdc-button size="small" @click="editSource(row)">编辑</cdc-button><cdc-button circle size="small" type="danger" plain title="删除连接" aria-label="删除连接" @click="remove('source',row)"><Trash2 :size="14"/></cdc-button></div></template></cdc-table-column></cdc-table></section>
      <section class="panel connections-panel" v-else><cdc-table :data="store.targets"><cdc-table-column prop="name" label="名称" min-width="180"/><cdc-table-column prop="targetType" label="类型" min-width="190"/><cdc-table-column label="目标" min-width="230"><template #default="{row}"><span class="mono">{{row.config.database||row.config.bootstrapServers||'-'}}</span></template></cdc-table-column><cdc-table-column label="状态" width="90"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></cdc-table-column><cdc-table-column label="操作" width="230"><template #default="{row}"><div class="connection-actions"><cdc-button size="small" @click="probe('target',row)"><PlugZap :size="14"/>测试</cdc-button><cdc-button size="small" @click="editTarget(row)">编辑</cdc-button><cdc-button circle size="small" type="danger" plain title="删除连接" aria-label="删除连接" @click="remove('target',row)"><Trash2 :size="14"/></cdc-button></div></template></cdc-table-column></cdc-table></section>
    </section>
  </div>
  <cdc-modal v-model="dialog" width="min(650px,94vw)" :title="title">
    <cdc-form v-if="kind==='source'" label-position="top"><div class="two-cols"><cdc-form-item label="连接名称" required><cdc-input v-model="sourceForm.name"/></cdc-form-item><cdc-form-item label="数据库类型"><cdc-select v-model="sourceForm.dbType" style="width:100%" @change="sourceTypeChanged"><cdc-option label="MySQL" value="MYSQL"/><cdc-option label="SQL Server" value="SQLSERVER"/><cdc-option label="StarRocks（轮询）" value="STARROCKS"/></cdc-select></cdc-form-item><cdc-form-item label="主机"><cdc-input v-model="sourceForm.host"/></cdc-form-item><cdc-form-item label="端口"><cdc-input-number v-model="sourceForm.port" :min="1" :max="65535" style="width:100%"/></cdc-form-item><cdc-form-item label="用户名"><cdc-input v-model="sourceForm.username"/></cdc-form-item><cdc-form-item label="密码"><cdc-input v-model="sourceForm.password" type="password" show-password :placeholder="sourceForm.id?'留空表示不修改':''"/></cdc-form-item><cdc-form-item label="轮询间隔（毫秒）"><cdc-input-number v-model="sourceForm.pollIntervalMs" :min="100" style="width:100%"/></cdc-form-item><cdc-form-item label="状态"><cdc-switch v-model="sourceForm.enabled" active-text="启用"/></cdc-form-item></div></cdc-form>
    <cdc-form v-else label-position="top"><div class="two-cols"><cdc-form-item label="连接名称" required><cdc-input v-model="targetForm.name"/></cdc-form-item><cdc-form-item label="目标类型"><cdc-select v-model="targetForm.targetType" style="width:100%"><cdc-option label="StarRocks Stream Load" value="STARROCKS_STREAM_LOAD"/><cdc-option label="MySQL" value="MYSQL"/><cdc-option label="SQL Server" value="SQLSERVER"/><cdc-option label="Kafka" value="KAFKA"/></cdc-select></cdc-form-item></div><template v-if="targetForm.targetType==='KAFKA'"><cdc-form-item label="Bootstrap Servers"><cdc-input v-model="targetForm.bootstrapServers"/></cdc-form-item></template><template v-else><div v-if="targetForm.targetType==='STARROCKS_STREAM_LOAD'" class="two-cols"><cdc-form-item label="Stream Load 地址"><cdc-input v-model="targetForm.endpoint" placeholder="http://127.0.0.1:18030"/></cdc-form-item><cdc-form-item label="查询端口"><cdc-input-number v-model="targetForm.queryPort" :min="1" :max="65535" style="width:100%"/></cdc-form-item></div><div v-else class="two-cols"><cdc-form-item label="主机"><cdc-input v-model="targetForm.host"/></cdc-form-item><cdc-form-item label="端口"><cdc-input-number v-model="targetForm.port" :min="1" :max="65535" style="width:100%"/></cdc-form-item></div><div class="two-cols"><cdc-form-item label="数据库"><cdc-input v-model="targetForm.database"/></cdc-form-item><span></span><cdc-form-item label="用户名"><cdc-input v-model="targetForm.username"/></cdc-form-item><cdc-form-item label="密码"><cdc-input v-model="targetForm.password" type="password" show-password :placeholder="targetForm.id?'留空表示不修改':''"/></cdc-form-item></div></template><cdc-form-item label="状态"><cdc-switch v-model="targetForm.enabled" active-text="启用"/></cdc-form-item></cdc-form>
    <template #footer><cdc-button @click="dialog=false">取消</cdc-button><cdc-button type="primary" :loading="loading" @click="save">保存连接</cdc-button></template>
  </cdc-modal>
</template>

<style scoped>
.connections-panel :deep(td:last-child) { white-space: nowrap; }
</style>
